import{_ as i,C as t,o as r,c as l,a4 as n,E as o}from"./chunks/framework.BNWYI55R.js";const f=JSON.parse('{"title":"隐私政策与数据安全：零追踪、无日志与本地优先原则","description":"aijichang.blog 隐私政策。我们尊重用户隐私，坚持零第三方追踪脚本、纯静态托管与本地浏览器计算原则。","frontmatter":{"title":"隐私政策与数据安全：零追踪、无日志与本地优先原则","description":"aijichang.blog 隐私政策。我们尊重用户隐私，坚持零第三方追踪脚本、纯静态托管与本地浏览器计算原则。","h1":"隐私政策与数据安全：零追踪、无日志与本地优先原则","pageType":"article","canonicalPath":"/privacy/","primaryIntent":"隐私政策：说明本站的数据收集政策、Cookie使用与本地计算原则","verifiedAt":"2026-10-21T00:00:00.000Z","modifiedAt":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md","lastUpdated":null}'),s={name:"privacy/index.md"};function d(c,a,h,_,p,u){const e=t("RelatedLinks");return r(),l("div",null,[a[0]||(a[0]=n('<h1 id="隐私政策与数据安全-零追踪、无日志与本地优先原则" tabindex="-1">隐私政策与数据安全：零追踪、无日志与本地优先原则 <a class="header-anchor" href="#隐私政策与数据安全-零追踪、无日志与本地优先原则" aria-label="Permalink to &quot;隐私政策与数据安全：零追踪、无日志与本地优先原则&quot;">​</a></h1><p>在 aijichang.blog，我们坚信：<strong>真正尊重用户的网站，应当从源头上杜绝不必要的用户数据收集。</strong></p><p>本页面公开我们在用户隐私与数据安全方面的严格承诺。</p><hr><h2 id="_1-零第三方侵入式追踪脚本" tabindex="-1">1. 零第三方侵入式追踪脚本 <a class="header-anchor" href="#_1-零第三方侵入式追踪脚本" aria-label="Permalink to &quot;1. 零第三方侵入式追踪脚本&quot;">​</a></h2><ul><li>本站<strong>不嵌入</strong>任何可能跨站追踪用户浏览习惯的商业第三方 SDK（如第三方广告追踪探针、用户画像收集插件等）；</li><li>本站不强制要求用户注册个人账户，不收集用户的手机号、真实姓名、个人通讯录等敏感身份信息。</li></ul><hr><h2 id="_2-纯静态架构与服务器日志" tabindex="-1">2. 纯静态架构与服务器日志 <a class="header-anchor" href="#_2-纯静态架构与服务器日志" aria-label="Permalink to &quot;2. 纯静态架构与服务器日志&quot;">​</a></h2><ul><li>本站采用 VitePress 编译为纯静态 HTML/CSS/JS 文件，托管于 Apache 静态服务器；</li><li>Web 服务器按行业网络安全规范记录基础访问日志（包括访问时间、请求路径、User-Agent 及掩码后的 IP 地址），此类日志仅用于防御恶意 DDoS 攻击与扫描，定期轮转清理，绝不用于商业用户画像。</li></ul><hr><h2 id="_3-本地优先与浏览器端计算" tabindex="-1">3. 本地优先与浏览器端计算 <a class="header-anchor" href="#_3-本地优先与浏览器端计算" aria-label="Permalink to &quot;3. 本地优先与浏览器端计算&quot;">​</a></h2><ul><li>本站提供的所有交互工具（如 7 大预算流量计算器、地区匹配器等），所有逻辑均通过轻量级 JavaScript 在你的<strong>本地浏览器内实时执行</strong>；</li><li>输入的数据不会以任何形式上传或回传至本站服务器，关闭页面后数据即自动在内存中销毁。</li></ul><hr><h2 id="_4-本地搜索与-pagefind-原理" tabindex="-1">4. 本地搜索与 Pagefind 原理 <a class="header-anchor" href="#_4-本地搜索与-pagefind-原理" aria-label="Permalink to &quot;4. 本地搜索与 Pagefind 原理&quot;">​</a></h2><ul><li>本站站内搜索使用 Pagefind 纯静态方案；</li><li>搜索索引以切片形式静态托管，用户在搜索框中输入的任何关键词均在浏览器本地通过 WebAssembly (WASM) 进行离线匹配，<strong>你的搜索词不会被记录或上报</strong>。</li></ul><hr><h2 id="_5-外部链接免责" tabindex="-1">5. 外部链接免责 <a class="header-anchor" href="#_5-外部链接免责" aria-label="Permalink to &quot;5. 外部链接免责&quot;">​</a></h2><p>本站包含指向第三方服务商官网的外部链接。当你点击这些链接离开本站后，请参阅该目标网站自身公布的隐私政策，本站不对第三方的隐私行为承担法律责任。</p>',18)),o(e,{links:[{title:"返回全站首页 (/) ",desc:"浏览综合选型工作台与核心推荐看板",url:"/"},{title:"商业披露与中立宣言 (/disclosure/)",desc:"查阅本站的推广佣金分成白皮书与中立底线",url:"/disclosure/"}]})])}const m=i(s,[["render",d]]);export{f as __pageData,m as default};
